INSERT INTO chapters(module_id,title,title_translation,description,description_translation,planned_lesson_count,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES(v_module,'Hallo und Namen','سلام و نام','Raha erlebt ihre ersten kurzen, natürlichen Begegnungen in Berlin: begrüßen, den Namen sagen, nach dem Namen fragen und sich verabschieden.','رها اولین برخوردهای کوتاه و طبیعی خود را در برلین تجربه می‌کند: سلام کردن، گفتن نام، پرسیدن نام و خداحافظی.',4,1,1,1,'validated',JSON_OBJECT('series',1,'contractVersion','3.0.0','foundationRevision','3.2.0','qualityRevision','3.2.1'));
