INSERT INTO sem_learning_units(course_id,unit_type,unit_key,display_form,translation,description_fa,cefr_level,difficulty,data,metadata) VALUES
(v_course,'word_sense','de:a1:hallo:greeting','Hallo','سلام','سلام روزمره و خنثی برای شروع یک برخورد کوتاه','A1',1,JSON_OBJECT('series',1),JSON_OBJECT('series',1)),(v_course,'chunk','de:a1:guten-morgen','Guten Morgen','صبح بخیر','سلام رایج در صبح','A1',1,JSON_OBJECT('series',1),JSON_OBJECT('series',1)),(v_course,'chunk','de:a1:ich-heisse','Ich heiße ...','اسم من ... است','الگوی اصلی معرفی نام','A1',1,JSON_OBJECT('series',1),JSON_OBJECT('series',1)),(v_course,'chunk','de:a1:wie-heisst-du','Wie heißt du?','اسمت چیه؟','پرسیدن نام با du در گفتگوی غیررسمی','A1',1,JSON_OBJECT('series',1),JSON_OBJECT('series',1)),(v_course,'chunk','de:a1:freut-mich','Freut mich.','از آشنایی با تو خوشحالم','واکنش کوتاه و طبیعی بعد از معرفی','A1',1,JSON_OBJECT('series',1),JSON_OBJECT('series',1)),(v_course,'pronunciation','de:a1:pron:h','h am Wortanfang','صدای h در ابتدای واژه','برای فارسی‌زبان: h در Hallo شنیده و تولید شود و حذف نشود.','A1',1,JSON_OBJECT('series',1),JSON_OBJECT('series',1)),(v_course,'can_do','de:a1:can:greet-name','Begrüßen und den Namen sagen','سلام کردن و گفتن نام','شروع و پایان یک آشنایی خیلی کوتاه و گفتن نام','A1',1,JSON_OBJECT('series',1),JSON_OBJECT('series',1)) ON DUPLICATE KEY UPDATE display_form=VALUES(display_form),translation=VALUES(translation),description_fa=VALUES(description_fa);
