INSERT INTO sem_curriculum_outcomes(course_id,cefr_level,outcome_key,outcome_type,title,description_fa,required,status,evidence,metadata) VALUES(v_course,'A1','can_do:greet_name','can_do','Begrüßen und Namen nennen','سلام و گفتن نام',1,'in_progress',JSON_ARRAY(),JSON_OBJECT('series',1)),(v_course,'A1','pron:word_initial_h','pronunciation','h am Wortanfang','شنیدن و تولید h ابتدای واژه',1,'in_progress',JSON_ARRAY(),JSON_OBJECT('series',1)),(v_course,'A1','reading:short_identity','reading','Kurze Identität lesen','خواندن معرفی کوتاه',1,'in_progress',JSON_ARRAY(),JSON_OBJECT('series',1)),(v_course,'A1','listening:basic_greeting','listening','Begrüßung verstehen','فهم سلام و معرفی نام',1,'in_progress',JSON_ARRAY(),JSON_OBJECT('series',1)) ON DUPLICATE KEY UPDATE status='in_progress';
INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES
(v_chapter,v_c_lena,v_c_raha,'Erstes Hallo','اولین سلام','Lena trifft Raha zum ersten Mal im Hausflur.','لنا برای اولین بار رها را در راهرو می‌بیند.','story','berlin_new_start',1,1,420,1,'validated',JSON_OBJECT('pedagogicalRole','exposure')),
(v_chapter,v_c_lena,v_c_raha,'Guten Morgen','صبح بخیر','Am nächsten Morgen begegnen sie sich wieder; Lena fragt nach Rahas Namen, weil die erste Begegnung kurz war.','صبح روز بعد دوباره همدیگر را می‌بینند؛ لنا چون دیدار اول کوتاه بوده نام رها را دوباره می‌پرسد.','story','berlin_new_start',2,1,420,2,'validated',JSON_OBJECT('pedagogicalRole','explicit_form')),
(v_chapter,v_c_lena,v_c_raha,'Kurz üben','تمرین کوتاه','Lena und Raha üben eine Mini-Begegnung; die Antworten werden zunehmend aus dem Gedächtnis abgerufen.','لنا و رها یک آشنایی کوتاه را تمرین می‌کنند و پاسخ‌ها کم‌کم از حافظه بازیابی می‌شوند.','story','berlin_new_start',3,1,420,3,'validated',JSON_OBJECT('pedagogicalRole','retrieval')),
(v_chapter,v_c_lena,v_c_raha,'Bereit für ein Treffen','آماده یک دیدار','Vor einem Treffen probt Raha nur kurz mit Lena; die eigentliche Meisterschaft wird danach in neuen Situationen geprüft.','رها پیش از یک دیدار فقط کوتاه با لنا تمرین می‌کند و سپس در موقعیت‌های تازه مستقلا سنجیده می‌شود.','story','berlin_new_start',4,1,480,4,'validated',JSON_OBJECT('pedagogicalRole','mastery'));
