INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count,evidence_activity_ids,metadata) SELECT v_l_1,id,'new',1,2,JSON_ARRAY(),JSON_OBJECT('series',1) FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:hallo:greeting','de:a1:guten-morgen','de:a1:ich-heisse','de:a1:wie-heisst-du','de:a1:freut-mich','de:a1:pron:h','de:a1:can:greet-name');
INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count,evidence_activity_ids,metadata) SELECT v_l_4,id,'mastery',1,1,JSON_ARRAY(),JSON_OBJECT('series',1) FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:hallo:greeting','de:a1:guten-morgen','de:a1:ich-heisse','de:a1:wie-heisst-du','de:a1:freut-mich','de:a1:pron:h','de:a1:can:greet-name');
INSERT IGNORE INTO sem_turn_learning_units(turn_id,learning_unit_id,evidence_type,metadata) SELECT t.id,lu.id,'mastery',JSON_OBJECT('series',1) FROM turns t JOIN sem_learning_units lu ON lu.course_id=v_course AND lu.unit_key='de:a1:can:greet-name' WHERE t.lesson_id=v_l_4 AND t.sort_order=4 LIMIT 1;
INSERT IGNORE INTO sem_review_obligations(course_id,learning_unit_id,origin_chapter_id,due_series,spacing_offset,status,metadata) SELECT v_course,lu.id,v_chapter,1+o.off,o.off,'due',JSON_OBJECT('originSeries',1) FROM sem_learning_units lu JOIN(SELECT 1 off UNION ALL SELECT 2 UNION ALL SELECT 4 UNION ALL SELECT 8 UNION ALL SELECT 16)o WHERE lu.course_id=v_course AND lu.unit_key IN('de:a1:hallo:greeting','de:a1:guten-morgen','de:a1:ich-heisse','de:a1:wie-heisst-du','de:a1:freut-mich','de:a1:pron:h','de:a1:can:greet-name');
